package glitch

import data.glitch_lib

# Detect non-exhaustive conditional statements (CWE-478)
# Focus on multi-branch conditionals without default/else fallback

# Check if a conditional statement has an else/default branch
has_else_branch(cond) {
    cond.else_statement != null
    cond.else_statement.ir_type == "ConditionalStatement"
} else {
    cond.is_default == true
}

# Count discrete branches in a conditional chain
count_branches(cond) = n {
    branches := {c |
        walk(cond, [_, c])
        c.ir_type == "ConditionalStatement"
        c.is_default == false
    }
    n := count(branches)
}

# Get the terminal else branch (the very last one in the chain, which should be default)
get_terminal_else(cond) = terminal {
    cond.else_statement != null
    cond.else_statement.ir_type == "ConditionalStatement"
    not cond.else_statement.else_statement
    terminal := cond.else_statement
} else {
    cond.else_statement != null
    cond.else_statement.ir_type == "ConditionalStatement"
    terminal := get_terminal_else(cond.else_statement)
}

# Check if terminal branch is a proper default (unconditional or catch-all)
is_proper_default(terminal) {
    terminal.is_default == true
} else {
    # Check if condition is a literal true or always-truthy pattern
    terminal.condition.ir_type == "Boolean"
    terminal.condition.value == true
}

# Main rule: detect switch-type conditionals with 3+ branches but no proper default
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Find conditional statements
    conditions := glitch_lib.all_conditional_statements(parent)
    cond := conditions[_]

    # Must be top-level conditional (not nested else)
    cond.is_top == true

    # Must be switch-type or have multiple if-elif branches
    count_branches(cond) >= 3

    # Check if there's a proper else/default branch
    not has_proper_default_fallback(cond)

    result := {
        "type": "sec_no_default_switch",
        "element": cond,
        "path": parent.path,
        "description": "Missing default case in multiple condition expression - Conditional logic with multiple branches lacks a proper default/fallback case, allowing unhandled values to propagate silently. (CWE-478)"
    }
}

# Helper to check if conditional has proper default fallback
has_proper_default_fallback(cond) {
    cond.else_statement != null
    terminal := get_terminal_else(cond)
    is_proper_default(terminal)
} else {
    cond.is_default == true
}

# Secondary rule: detect if-elif chains without any else (3+ branches)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    conditions := glitch_lib.all_conditional_statements(parent)
    cond := conditions[_]

    cond.is_top == true
    cond.type == 1  # IF type

    # Count elif branches (else_statement that is not default)
    count_branches(cond) >= 3

    # No else statement at all
    cond.else_statement == null

    result := {
        "type": "sec_no_default_switch",
        "element": cond,
        "path": parent.path,
        "description": "Missing default case in multiple condition expression - If-elif chain with multiple branches lacks an else clause, potentially leaving values unhandled. (CWE-478)"
    }
}

# Tertiary rule: detect conditionals on variable inputs without exhaustive handling
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    conditions := glitch_lib.all_conditional_statements(parent)
    cond := conditions[_]

    cond.is_top == true

    # Condition involves a variable reference (external input)
    condition_uses_variable(cond.condition)

    # Has multiple branches but no proper default
    count_branches(cond) >= 2
    not has_proper_default_fallback(cond)

    # Check if this affects security-critical configuration
    affects_security_configuration(parent, cond)

    result := {
        "type": "sec_no_default_switch",
        "element": cond,
        "path": parent.path,
        "description": "Missing default case in multiple condition expression - Input-driven conditional without exhaustive handling, with potential impact on security configuration. (CWE-478)"
    }
}

# Check if condition uses a variable reference (external/untrusted input)
condition_uses_variable(expr) {
    walk(expr, [_, n])
    n.ir_type == "VariableReference"
}

# Check if conditional affects security-related configuration
affects_security_configuration(parent, cond) {
    # Check if any attribute in affected scope relates to security
    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    security_related_attr(attr.name)
}

# Security-related attribute names (general, provider-agnostic)
